from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if new in text:
        return
    if old not in text:
        raise AssertionError(f"pattern not found in {path}: {old[:100]!r}")
    p.write_text(text.replace(old, new, 1))


